fn clone_type(&mut self, ty: &ResolvedType) -> Result<ResolvedType, Diagnostic> {
    Self::authenticate()?;
    if !self.clone_cursor_paid {
        pay(Some(size_of::<[Option<(&ResolvedType, usize)>; 514]>()))?;
        self.clone_cursor_paid = true;
    }
    pay(ty.clone_payload_bytes())?;
    Ok(ty.clone())
}
